                int v = to[e];
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    queue[qt++] = v;
                }
            }
        }
        return farthest;
    }

    static int countAtDepth(int u, int p, int d, int target) {
        if (d == target) return 1;
        int count = 0;
        for (int e = head[u]; e != -1; e = next[e]) {
            int v = to[e];
            if (v != p) {
                count += countAtDepth(v, u, d + 1, target);
            }
        }
        return count;
    }

